function json(data, status = 200, headers = {}) {
  return new Response(JSON.stringify(data), { status, headers: { ...JSON_HEADERS, ...headers } });
}
function b64url(bytes) {
  let s = ""; for (const b of new Uint8Array(bytes)) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}
function fromB64url(value) {
  const s = value.replace(/-/g, "+").replace(/_/g, "/");
  return Uint8Array.from(atob(s + "=".repeat((4 - s.length % 4) % 4)), c => c.charCodeAt(0));
}
function randomToken(size = 32) { const bytes = crypto.getRandomValues(new Uint8Array(size)); return b64url(bytes); }
async function sha256(value) { return b64url(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value))); }
function cookieValue(request, name) {
  const raw = request.headers.get("Cookie") || "";
  for (const part of raw.split(";")) { const [k, ...v] = part.trim().split("="); if (k === name) return v.join("="); }
  return null;
}
function setCookie(token, maxAge) {
  return `${SESSION_COOKIE}=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`;
}
function clearCookie() { return `${SESSION_COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`; }
function safeJson(value, fallback) { try { return value ? JSON.parse(value) : fallback; } catch { return fallback; } }
function validEmail(email) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email) && email.length <= 254; }
function sameOrigin(request) {
  const origin = request.headers.get("Origin");
  return !origin || origin === new URL(request.url).origin;
}
function cleanUser(row) {
  return {
    id: row.id, name: row.name, email: row.email, phone: row.phone || "",
    role: row.role || "Personal", memberId: row.member_id,
    favorites: safeJson(row.favorites_json, []), pins: safeJson(row.pins_json, []), history: safeJson(row.history_json, []),
    authProvider: row.auth_provider || "password"
  };
}
async function bodyJson(request) {
  const text = await request.text();
  if (text.length > 30000) throw new Error("Request payload too large");
  return JSON.parse(text || "{}");
}
async function hashPassword(password, salt = crypto.getRandomValues(new Uint8Array(16))) {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", salt, iterations: PBKDF2_ITERATIONS, hash: "SHA-256" }, key, 256);
  return { salt: b64url(salt), hash: b64url(bits) };
}
async function verifyPassword(password, salt, expected) {
  const result = await hashPassword(password, fromB64url(salt));
  const a = fromB64url(result.hash), b = fromB64url(expected);
  if (a.length !== b.length) return false;
  let diff = 0; for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

// Rate Limiting & Brute-Force Protection
async function checkRateLimit(env, key) {
  const now = Date.now();
  let rec = EDGE_RATE_LIMITS.get(key);
  if (!rec && env && env.DB) {
    try {
      const row = await env.DB.prepare("SELECT attempts, locked_until FROM login_attempts WHERE key=? LIMIT 1").bind(key).first();
      if (row) rec = { attempts: Number(row.attempts), lockedUntil: Number(row.locked_until) };
    } catch (_) {}
  }
  if (rec && rec.lockedUntil > now) {
    const mins = Math.max(1, Math.ceil((rec.lockedUntil - now) / 60000));
    return { blocked: true, message: `Too many failed attempts. Try again in ${mins} minute(s).` };
  }
  return { blocked: false };
}

async function recordFailedAttempt(env, key) {
  const now = Date.now();
  const prev = EDGE_RATE_LIMITS.get(key) || { attempts: 0, lockedUntil: 0 };
  const attempts = prev.lockedUntil < now && prev.attempts >= MAX_LOGIN_ATTEMPTS ? 1 : prev.attempts + 1;
  const lockedUntil = attempts >= MAX_LOGIN_ATTEMPTS ? now + LOCKOUT_WINDOW_MS : 0;
  EDGE_RATE_LIMITS.set(key, { attempts, lockedUntil });
  if (env && env.DB) {
    try {
      await env.DB.prepare("INSERT OR REPLACE INTO login_attempts (key, attempts, locked_until) VALUES (?, ?, ?)").bind(key, attempts, lockedUntil).run();
    } catch (_) {}
  }
}

async function clearRateLimit(env, key) {
  EDGE_RATE_LIMITS.delete(key);
  if (env && env.DB) {
    try { await env.DB.prepare("DELETE FROM login_attempts WHERE key=?").bind(key).run(); } catch (_) {}
  }
}

// Server-Side Google ID Token Verification
async function verifyGoogleIdToken(credential, expectedClientId) {
  if (!credential || credential.length > 10000) throw new Error("Missing or invalid Google ID token");
  const resp = await fetch("https://oauth2.googleapis.com/tokeninfo?id_token=" + encodeURIComponent(credential));
  if (!resp.ok) throw new Error("Google ID token verification failed");
  const info = await resp.json();
  const validIssuer = info.iss === "accounts.google.com" || info.iss === "https://accounts.google.com";
  const notExpired = Number(info.exp) * 1000 > Date.now();
  const audMatches = !expectedClientId || info.aud === expectedClientId;
  if (!validIssuer || !notExpired || info.email_verified !== "true" || !audMatches) {
    throw new Error("Google account verification rejected (token or Client ID mismatch)");
  }
  const email = String(info.email || "").trim().toLowerCase();
  if (!validEmail(email)) throw new Error("Google did not provide a verified email");
  return {
    email,
    name: String(info.name || info.given_name || email.split("@")[0]).slice(0, 100),
    googleSub: String(info.sub || "")
  };
}

let d1SchemaReady = false;
async function ensureD1Schema(env) {
  if (!env || !env.DB || d1SchemaReady) return;
  try {
    await env.DB.batch([
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        email TEXT NOT NULL UNIQUE,
        phone TEXT DEFAULT '',
        role TEXT DEFAULT 'Personal',
        member_id TEXT NOT NULL,
        password_hash TEXT DEFAULT '',
        password_salt TEXT DEFAULT '',
        auth_provider TEXT DEFAULT 'password',
        google_sub TEXT DEFAULT '',
        favorites_json TEXT DEFAULT '[]',
        pins_json TEXT DEFAULT '[]',
        history_json TEXT DEFAULT '[]',
        created_at TEXT NOT NULL,
        updated_at TEXT DEFAULT ''
      )`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS sessions (
        token_hash TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        expires_at TEXT NOT NULL,
        created_at TEXT NOT NULL
      )`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS password_resets (
        email TEXT PRIMARY KEY,
        code TEXT NOT NULL,
        expires_at INTEGER NOT NULL
      )`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS login_attempts (
        key TEXT PRIMARY KEY,
        attempts INTEGER NOT NULL,
        locked_until INTEGER NOT NULL
      )`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS donations (
        id TEXT PRIMARY KEY,
        amount REAL NOT NULL,
        method TEXT NOT NULL,
        note TEXT DEFAULT '',
        donor_email TEXT DEFAULT '',
        created_at TEXT NOT NULL
      )`)
    ]);
    d1SchemaReady = true;
  } catch (_) {}
}

async function createSession(env, userId, remember) {
  const token = randomToken(32), tokenHash = await sha256(token);
  const ttl = remember ? SESSION_TTL_SECONDS : 60 * 60 * 12;
  const expires = new Date(Date.now() + ttl * 1000).toISOString();
  EDGE_SESSIONS.set(tokenHash, { userId, expiresAt: expires });
  if (env && env.DB) {
    try {
      await env.DB.prepare("INSERT INTO sessions (token_hash, user_id, expires_at, created_at) VALUES (?, ?, ?, ?)").bind(tokenHash, userId, expires, new Date().toISOString()).run();
    } catch (_) {}
  }
  return { token, ttl };
}

async function sessionUser(request, env) {
  const token = cookieValue(request, SESSION_COOKIE); if (!token) return null;
  const tokenHash = await sha256(token);
  if (env && env.DB) {
    try {
      const row = await env.DB.prepare("SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at > ? LIMIT 1").bind(tokenHash, new Date().toISOString()).first();
      if (row) return row;
    } catch (_) {}
  }
  const sess = EDGE_SESSIONS.get(tokenHash);
  if (!sess || sess.expiresAt <= new Date().toISOString()) return null;
  for (const u of EDGE_USERS.values()) { if (u.id === sess.userId) return u; }
  return null;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url), path = url.pathname;
    const clientIp = request.headers.get("CF-Connecting-IP") || "unknown";

    if (path.startsWith("/api/")) {
      await ensureD1Schema(env);
      if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: { "allow": "GET, POST, OPTIONS", ...SECURITY_HEADERS } });
      if (request.method === "POST" && !sameOrigin(request)) return json({ ok: false, error: "Cross-origin request blocked" }, 403);

      try {
        if (path === "/api/config" && request.method === "GET") {
          return json({ ok: true, version: "2.0", googleClientId: (env && env.GOOGLE_CLIENT_ID) || "", hasDatabase: Boolean(env && env.DB) });
        }

        if (path === "/api/auth/signup" && request.method === "POST") {
          const rl = await checkRateLimit(env, "signup:" + clientIp);
          if (rl.blocked) return json({ ok: false, error: rl.message }, 429);

          const body = await bodyJson(request);
          const name = String(body.name || "").trim(), email = String(body.email || "").trim().toLowerCase(), password = String(body.password || "");
          if (name.length < 2 || name.length > 100 || !validEmail(email)) return json({ ok: false, error: "Enter a valid name and email address" }, 400);
          if (password.length < 4 || password.length > 128) return json({ ok: false, error: "Password must be 4–128 characters" }, 400);

          let existing = EDGE_USERS.get(email);
          if (!existing && env && env.DB) {
            try { existing = await env.DB.prepare("SELECT id FROM users WHERE email=? LIMIT 1").bind(email).first(); } catch (_) {}
          }
          if (existing) return json({ ok: false, error: "An account with this email already exists" }, 409);

          const pw = await hashPassword(password), id = crypto.randomUUID(), memberId = "CV-" + randomToken(4).toUpperCase();
          const createdAt = new Date().toISOString();
          const favJson = JSON.stringify(Array.isArray(body.favorites) ? body.favorites.slice(0, 100) : ["mortgage", "bmi", "compound", "graphing"]);
          const pinsJson = JSON.stringify(Array.isArray(body.pins) ? body.pins.slice(0, 100) : []);
          const histJson = JSON.stringify(Array.isArray(body.history) ? body.history.slice(0, 200) : []);
          const rowObj = {
            id, name, email, phone: String(body.phone || "").slice(0, 30), role: String(body.role || "Personal").slice(0, 40),
            member_id: memberId, password_hash: pw.hash, password_salt: pw.salt, auth_provider: "password",
            favorites_json: favJson, pins_json: pinsJson, history_json: histJson, created_at: createdAt
          };
          EDGE_USERS.set(email, rowObj);
          if (env && env.DB) {
            await env.DB.prepare("INSERT INTO users (id,name,email,phone,role,member_id,password_hash,password_salt,auth_provider,favorites_json,pins_json,history_json,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)")
              .bind(id, name, email, rowObj.phone, rowObj.role, memberId, pw.hash, pw.salt, "password", favJson, pinsJson, histJson, createdAt).run();
          }
          const session = await createSession(env, id, true);
          return json({ ok: true, user: cleanUser(rowObj) }, 201, { "set-cookie": setCookie(session.token, session.ttl) });
        }

        if (path === "/api/auth/login" && request.method === "POST") {
          const body = await bodyJson(request);
          const email = String(body.email || "").trim().toLowerCase(), password = String(body.password || "");
          const rlKey = `login:${clientIp}:${email}`;
          const rl = await checkRateLimit(env, rlKey);
          if (rl.blocked) return json({ ok: false, error: rl.message }, 429);

          let row = EDGE_USERS.get(email);
          if (!row && env && env.DB) {
            try { row = await env.DB.prepare("SELECT * FROM users WHERE email=? LIMIT 1").bind(email).first(); } catch (_) {}
          }
          if (!row || !row.password_hash || !(await verifyPassword(password, row.password_salt, row.password_hash))) {
            await recordFailedAttempt(env, rlKey);
            return json({ ok: false, error: "Invalid email or password" }, 401);
          }
          await clearRateLimit(env, rlKey);
          const session = await createSession(env, row.id, body.remember !== false);
          return json({ ok: true, user: cleanUser(row) }, 200, { "set-cookie": setCookie(session.token, session.ttl) });
        }

        if (path === "/api/auth/google" && request.method === "POST") {
          const body = await bodyJson(request);
          const google = await verifyGoogleIdToken(String(body.credential || ""), (env && env.GOOGLE_CLIENT_ID) || "");
          let row = EDGE_USERS.get(google.email);
          if (!row && env && env.DB) {
            try { row = await env.DB.prepare("SELECT * FROM users WHERE email=? LIMIT 1").bind(google.email).first(); } catch (_) {}
          }
          if (!row) {
            const id = crypto.randomUUID(), memberId = "CV-GGL-" + randomToken(4).toUpperCase(), createdAt = new Date().toISOString();
            row = {
              id, name: google.name, email: google.email, phone: "", role: "Personal", member_id: memberId,
              auth_provider: "google", google_sub: google.googleSub,
              favorites_json: '["mortgage","bmi","compound","graphing"]', pins_json: "[]", history_json: "[]", created_at: createdAt
            };
            EDGE_USERS.set(google.email, row);
            if (env && env.DB) {
              await env.DB.prepare("INSERT INTO users (id,name,email,role,member_id,auth_provider,google_sub,favorites_json,pins_json,history_json,created_at) VALUES (?,?,?,'Personal',?,'google',?,?, '[]','[]',?)")
                .bind(id, google.name, google.email, memberId, google.googleSub, row.favorites_json, createdAt).run();
            }
          } else if (row.google_sub && row.google_sub !== google.googleSub) {
            return json({ ok: false, error: "Google account does not match this profile" }, 403);
          } else if (!row.google_sub && env && env.DB) {
            await env.DB.prepare("UPDATE users SET google_sub=?, auth_provider='password+google' WHERE id=?").bind(google.googleSub, row.id).run();
            row.google_sub = google.googleSub;
            row.auth_provider = "password+google";
          }
          const session = await createSession(env, row.id, true);
          return json({ ok: true, user: cleanUser(row) }, 200, { "set-cookie": setCookie(session.token, session.ttl) });
        }

        if (path === "/api/auth/forgot" && request.method === "POST") {
          const rl = await checkRateLimit(env, "forgot:" + clientIp);
          if (rl.blocked) return json({ ok: false, error: rl.message }, 429);

          const body = await bodyJson(request);
          const email = String(body.email || "").trim().toLowerCase();
          let row = EDGE_USERS.get(email);
          if (!row && env && env.DB) {
            try { row = await env.DB.prepare("SELECT * FROM users WHERE email=? LIMIT 1").bind(email).first(); } catch (_) {}
          }
          if (!row) {
            await recordFailedAttempt(env, "forgot:" + clientIp);
            return json({ ok: false, error: "No account found with that email address" }, 404);
          }
          const code = String(Math.floor(100000 + Math.random() * 900000));
          const expiresAt = Date.now() + 15 * 60 * 1000;
          EDGE_RESET_CODES.set(email, { code, expiresAt });
          if (env && env.DB) {
            try { await env.DB.prepare("INSERT OR REPLACE INTO password_resets (email, code, expires_at) VALUES (?, ?, ?)").bind(email, code, expiresAt).run(); } catch (_) {}
          }
          let emailed = false;
          if (env && env.RESEND_API_KEY) {
            try {
              const mailRes = await fetch("https://api.resend.com/emails", {
                method: "POST",
                headers: { "Authorization": `Bearer ${env.RESEND_API_KEY}`, "Content-Type": "application/json" },
                body: JSON.stringify({
                  from: env.MAIL_FROM || "CalcVerse <onboarding@resend.dev>",
                  to: [email],
                  subject: "CalcVerse Password Reset Code",
                  text: `Your CalcVerse password reset code is: ${code} (expires in 15 minutes).`
                })
              });
              if (mailRes.ok) emailed = true;
            } catch (_) {}
          }
          return json({ ok: true, emailed, code: emailed ? undefined : code });
        }

        if (path === "/api/auth/reset" && request.method === "POST") {
          const body = await bodyJson(request);
          const email = String(body.email || "").trim().toLowerCase();
          const code = String(body.code || "").trim();
          const newPassword = String(body.newPassword || "");
          let entry = EDGE_RESET_CODES.get(email);
          if (!entry && env && env.DB) {
            try {
              const dbRow = await env.DB.prepare("SELECT code, expires_at FROM password_resets WHERE email=? LIMIT 1").bind(email).first();
              if (dbRow) entry = { code: dbRow.code, expiresAt: Number(dbRow.expires_at) };
            } catch (_) {}
          }
          if (!entry || entry.expiresAt < Date.now() || entry.code !== code) {
            return json({ ok: false, error: "Invalid or expired reset code" }, 400);
          }
          if (newPassword.length < 4) return json({ ok: false, error: "Password must be at least 4 characters" }, 400);
          const pw = await hashPassword(newPassword);
          const row = EDGE_USERS.get(email);
          if (row) { row.password_hash = pw.hash; row.password_salt = pw.salt; EDGE_USERS.set(email, row); }
          if (env && env.DB) {
            await env.DB.prepare("UPDATE users SET password_hash=?, password_salt=?, updated_at=? WHERE email=?").bind(pw.hash, pw.salt, new Date().toISOString(), email).run();
            await env.DB.prepare("DELETE FROM password_resets WHERE email=?").bind(email).run();
          }
          EDGE_RESET_CODES.delete(email);
          return json({ ok: true });
        }

        if (path === "/api/auth/me" && request.method === "GET") {
          const row = await sessionUser(request, env);
          return row ? json({ ok: true, user: cleanUser(row) }) : json({ ok: true, user: null });
        }

        if (path === "/api/auth/profile" && request.method === "POST") {
          const body = await bodyJson(request);
          const row = (await sessionUser(request, env)) || EDGE_USERS.get(String(body.email || "").toLowerCase());
          if (!row) return json({ ok: false, error: "Please sign in first" }, 401);
          const name = String(body.name || row.name).trim().slice(0, 100);
          const phone = String(body.phone || "").trim().slice(0, 30);
          const role = String(body.role || row.role || "Personal").trim().slice(0, 40);
          row.name = name; row.phone = phone; row.role = role;
          EDGE_USERS.set(row.email, row);
          if (env && env.DB) {
            await env.DB.prepare("UPDATE users SET name=?, phone=?, role=?, updated_at=? WHERE id=?").bind(name, phone, role, new Date().toISOString(), row.id).run();
          }
          return json({ ok: true, user: cleanUser(row) });
        }

        if (path === "/api/auth/sync" && request.method === "POST") {
          const body = await bodyJson(request);
          const row = (await sessionUser(request, env)) || EDGE_USERS.get(String(body.email || "").toLowerCase());
          if (!row) return json({ ok: false, error: "Please sign in again" }, 401);
          const favJson = JSON.stringify(Array.isArray(body.favorites) ? body.favorites.slice(0, 100) : []);
          const pinsJson = JSON.stringify(Array.isArray(body.pins) ? body.pins.slice(0, 100) : []);
          const histJson = JSON.stringify(Array.isArray(body.history) ? body.history.slice(0, 200) : []);
          row.favorites_json = favJson; row.pins_json = pinsJson; row.history_json = histJson;
          EDGE_USERS.set(row.email, row);
          if (env && env.DB) {
            await env.DB.prepare("UPDATE users SET favorites_json=?, pins_json=?, history_json=?, updated_at=? WHERE id=?").bind(favJson, pinsJson, histJson, new Date().toISOString(), row.id).run();
          }
          return json({ ok: true });
        }

        if (path === "/api/auth/logout" && request.method === "POST") {
          const token = cookieValue(request, SESSION_COOKIE);
          if (token) {
            const th = await sha256(token);
            EDGE_SESSIONS.delete(th);
            if (env && env.DB) {
              try { await env.DB.prepare("DELETE FROM sessions WHERE token_hash=?").bind(th).run(); } catch (_) {}
            }
          }
          return json({ ok: true }, 200, { "set-cookie": clearCookie() });
        }

        if (path.startsWith("/api/admin/")) {
          const rl = await checkRateLimit(env, "admin:" + clientIp);
          if (rl.blocked) return json({ ok: false, error: rl.message }, 429);
          const expectedKey = String((env && env.ADMIN_KEY) || "").trim();
          if (!expectedKey) {
            return json({ ok: false, error: "ADMIN_KEY is not configured in Cloudflare Worker Variables & Secrets yet." }, 503);
          }
          const suppliedKey = String(request.headers.get("x-admin-key") || "").trim();
          if (suppliedKey.length !== expectedKey.length) {
            await recordFailedAttempt(env, "admin:" + clientIp);
            return json({ ok: false, error: "Unauthorized: Invalid ADMIN_KEY." }, 401);
          }
          let diff = 0;
          for (let i = 0; i < expectedKey.length; i++) diff |= expectedKey.charCodeAt(i) ^ suppliedKey.charCodeAt(i);
          if (diff !== 0) {
            await recordFailedAttempt(env, "admin:" + clientIp);
            return json({ ok: false, error: "Unauthorized: Invalid ADMIN_KEY." }, 401);
          }
          await clearRateLimit(env, "admin:" + clientIp);
          if (path === "/api/admin/verify" && request.method === "POST") {
            return json({ ok: true });
          }
        }

        if (path === "/api/admin/users" && request.method === "GET") {
          if (env && env.DB) {
            const rows = await env.DB.prepare("SELECT id, name, email, phone, role, member_id, auth_provider, created_at FROM users ORDER BY created_at DESC LIMIT 200").all();
            return json({ ok: true, storage: "Cloudflare D1", users: rows.results || [] });
          }
          const list = Array.from(EDGE_USERS.values()).map(u => ({
            id: u.id, name: u.name, email: u.email, phone: u.phone || "", role: u.role || "Personal",
            member_id: u.member_id, auth_provider: u.auth_provider || "password", created_at: u.created_at
          }));
          return json({ ok: true, storage: "Edge Memory (Bind D1 as DB)", users: list });
        }

        return json({ ok: false, error: "Not found" }, 404);
      } catch (err) {
        return json({ ok: false, error: err && err.message ? err.message : "Server error" }, 400);
      }
    }

    if (path === "/js/app.js" || path.endsWith("/app.js")) {
      return new Response(APP_JS, { headers: { "content-type": "application/javascript; charset=utf-8", "cache-control": "public, max-age=300", ...SECURITY_HEADERS } });
    }
    if (path === "/css/styles.css" || path.endsWith("/styles.css")) {
      return new Response(STYLES_CSS, { headers: { "content-type": "text/css; charset=utf-8", "cache-control": "public, max-age=300", ...SECURITY_HEADERS } });
    }
    if (path === "/ads.txt") return new Response(ADS_TXT, { headers: { "content-type": "text/plain; charset=utf-8", ...SECURITY_HEADERS } });
    if (path === "/robots.txt") return new Response(ROBOTS_TXT, { headers: { "content-type": "text/plain; charset=utf-8", ...SECURITY_HEADERS } });
    if (path === "/sitemap.xml") return new Response(SITEMAP_XML, { headers: { "content-type": "application/xml; charset=utf-8", ...SECURITY_HEADERS } });

    return new Response(HTML_APP, {
      headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", ...SECURITY_HEADERS }
    });
  }
};
